class Cell {
  constructor(coordinates) {
    this.coordinates = coordinates;
    this.edges = [];
    this.initial();
		this.area = calculatePolygonArea(this.coordinates);
  }

  initial() {
    // this.edges
    for (let i = 0; i < this.coordinates.length; i++) {
      const nextIndex = i < this.coordinates.length - 1 ? i + 1 : 0;
      this.edges.push([this.coordinates[i], this.coordinates[nextIndex]]);
    }

    this.center = this.coordinates[0].copy();
    for (let coordinate of this.coordinates) {
      this.center.lerp(coordinate, 0.5);
    }
  }

  draw() {
    push();
    // noFill();
    // stroke(255);
    // bezierCircle(this.coordinates);
    beginClip();
    bezierCircle(this.coordinates);
    endClip();
		background(0);
		push()
		fill("#FFFDEF")
		bezierCircle(this.coordinates);
		pop()
    // background("#FFFDEF");

		for(let edge of this.edges){
			const edgeVec = p5.Vector.sub(edge[0],edge[1])
			const edgeVecNormal = edgeVec.copy().rotate(PI/2).setMag(1)

			const range = sqrt(this.area)*0.8
			// const space = 5
			// const seg = floor(edgeVec.mag() / space)

			const pointCount = floor(edgeVec.mag()) * 5
			for(let i=0;i<pointCount;i++){
				// const t = map(i,0,seg,0,1)
				const t = random()
				const r = random(random(random()))*range
				const p = p5.Vector.lerp(edge[0],edge[1],t).add(edgeVecNormal.copy().mult(r))
				strokeWeight(map(r,0,range,1.7,0))
				stroke("#386642C6")
				point(p.x,p.y)
			}
		}

    stroke(255, 0, 0);
    strokeWeight(5);
    pop();
  }
}



