function bezierCircle(coordinates) {
  push();
  const bezierPoints = [];
  const ctrlPoints = [];
  for (let i = 0; i < coordinates.length; i++) {
    const nextIndex = i < coordinates.length - 1 ? i + 1 : 0;
    const start = coordinates[i];
    const end = coordinates[nextIndex];
    ctrlPoints.push([
      p5.Vector.lerp(start, end, 1 / 4),
      p5.Vector.lerp(start, end, 3 / 4),
    ]);
  }

  for (let i = 0; i < ctrlPoints.length; i++) {
    const lastIndex = i > 0 ? i - 1 : ctrlPoints.length - 1;
    const nextIndex = i < ctrlPoints.length - 1 ? i + 1 : 0;
    const lastSecPoint = ctrlPoints[lastIndex][1];
    const nextFirstPoint = ctrlPoints[nextIndex][0];
    // let start = p5.Vector.lerp(
    //   lastSecPoint.copy(),
    //   ctrlPoints[i][0].copy(),
    //   0.5
    // );
    const start = p5.Vector.lerp(lastSecPoint, ctrlPoints[i][0], 0.5);
    const end = p5.Vector.lerp(nextFirstPoint, ctrlPoints[i][1], 0.5);
    bezierPoints.push(start);
    bezierPoints.push(ctrlPoints[i][0]);
    bezierPoints.push(ctrlPoints[i][1]);
  }

  beginShape();
  vertex(bezierPoints[0].x, bezierPoints[0].y);
  for (let i = 0; i < bezierPoints.length; i += 3) {
    if (i === bezierPoints.length - 3) {
      bezierVertex(
        bezierPoints[bezierPoints.length - 2].x,
        bezierPoints[bezierPoints.length - 2].y,
        bezierPoints[bezierPoints.length - 1].x,
        bezierPoints[bezierPoints.length - 1].y,
        bezierPoints[0].x,
        bezierPoints[0].y
      );
    } else {
      bezierVertex(
        bezierPoints[i + 1].x,
        bezierPoints[i + 1].y,
        bezierPoints[i + 2].x,
        bezierPoints[i + 2].y,
        bezierPoints[i + 3].x,
        bezierPoints[i + 3].y
      );
    }
  }
  endShape();
  pop();
}

function calculatePolygonArea(vertices) {
  let area = 0;
  let n = vertices.length;

  // 遍歷所有頂點
  for (let i = 0; i < n; i++) {
    let j = (i + 1) % n; // 當 i 為最後一個索引時，j 指向第一個頂點
    area += vertices[i].x * vertices[j].y - vertices[j].x * vertices[i].y;
  }

  return Math.abs(area / 2.0); // 最後取絕對值並除以2
}

function calculateBoundingBox(polygon) {
  let minX = polygon[0].x;
  let maxX = polygon[0].x;
  let minY = polygon[0].y;
  let maxY = polygon[0].y;

  for (let i = 1; i < polygon.length; i++) {
    minX = min(minX, polygon[i].x);
    maxX = max(maxX, polygon[i].x);
    minY = min(minY, polygon[i].y);
    maxY = max(maxY, polygon[i].y);
  }

  return { minX, maxX, minY, maxY };
}

// 函數來檢查一個點是否在多邊形內部
function isPointInPolygon(point, polygon) {
  let count = 0;
  for (let i = 0; i < polygon.length; i++) {
    let next = (i + 1) % polygon.length;
    if ((polygon[i].y > point.y) != (polygon[next].y > point.y) &&
        (point.x < (polygon[next].x - polygon[i].x) * (point.y - polygon[i].y) / (polygon[next].y - polygon[i].y) + polygon[i].x)) {
      count++;
    }
  }
  return count % 2 != 0;
}

// 主函數來返回多邊形內部的隨機點
function randomPointInPolygon(polygon) {
  let bbox = calculateBoundingBox(polygon);
  let point;
	point = createVector(random(bbox.minX, bbox.maxX), random(bbox.minY, bbox.maxY));
  while (!isPointInPolygon(point, polygon)){
		point = createVector(random(bbox.minX, bbox.maxX), random(bbox.minY, bbox.maxY));
	}
	return point;
}

