/*
Plant Tissue
Made for #WCCChallenge topic "Connecting the dots ✏️" 2023.11.12. by 陳建中 Tân Kiàn-tiong（rainsr7235 on twitch）

During my RESEARCH,
This week's topic, "Connecting the dots," led me to discover 
something really cool: delaunay-triangulation and its good 
friend, the Voronoi diagram.

Initially, I wanted to implement them directly in JavaScript,
but they turned out to be quite complex. ChatGPT suggested 
using existing libraries, so I did just that :P

Delaunay-triangulation connects points to form a triangular
mesh, while the Voronoi diagram connects the circumcenters 
of these triangles. I really like the patterns created by 
the Voronoi diagram; I tried using it to draw images resembling
plant cell tissues, hoping everyone will like it.

BTW, I'm a bit short on time, so I only have a prototype for now.
I plan to enrich it later with more details, like the organelles
inside the cells.

The voronoi Library I used:https://github.com/gorhill/Javascript-Voronoi
*/

const cells = [];
const sites = [];
let bboxSide;
let diagram;
let mask;

function setup() {
  if (windowWidth > windowHeight) {
    bboxSide = windowHeight;
  } else {
    bboxSide = windowWidth;
  }
  createCanvas(bboxSide, bboxSide);
  background(0);

  const padding = 30;

	mask = createGraphics(width,height)
	mask.push()
	mask.beginClip({ invert: true })
	mask.circle(width/2,height/2,width-padding*2)
	mask.endClip()
	mask.background(0)
	mask.pop()

  push();
  fill("#162C1A");
  circle(width / 2, height / 2, bboxSide - padding);
  pop();

	const cellCount = floor(random(50,300))
  voronoiSetup(cellCount);

  for (let cell of cells) {
    cell.draw();
  }

	// for (let site of sites){
	// 	circle(site.x,site.y,10)
	// }

	image(mask,0,0)
}

function draw() {}

function voronoiSetup(cellCount) {
  const voronoi = new Voronoi();
  const bbox = {
    xl: 0,
    xr: bboxSide,
    yt: 0,
    yb: bboxSide,
  }; // xl is x-left, xr is x-right, yt is y-top, and yb is y-bottom


  for (let i = 0; i < cellCount; i++) {
    const angle = random(0, 2 * PI);
    const r = (1 - random(random(random()))) * width * 0.5;
    const x = width / 2 + cos(angle) * r;
    const y = height / 2 + sin(angle) * r;
    sites.push(createVector(x, y));
  }

  diagram = voronoi.compute(sites, bbox);

  for (let cell of diagram.cells) {
    // print(cell);
    fill(random(255), random(255), random(255));
    noStroke();
    // beginShape();
    const coordinates = [];
    for (let halfedge of cell.halfedges) {
      let edge = halfedge.getStartpoint();
      coordinates.push(createVector(edge.x, edge.y));
      // vertex(edge.x, edge.y);

    }
		const plantCell = new Cell(coordinates);
    cells.push(plantCell);
    // endShape(CLOSE);
  }

	// print(diagram.cells)
}


